components.css:
.ds-btn-primary { display: inline-flex; align-items: center; gap: 8px; background: #8B7CE8; color: #FFFFFF; border: 0; border-radius: 16px; padding: 14px 24px; font-family: Inter, sans-serif; font-size: 15px; font-weight: 600; cursor: pointer; transition: transform 220ms cubic-bezier(0.05, 0.7, 0.1, 1), background-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-btn-primary:hover { background: #9486EA; }
.ds-btn-primary:active { transform: scale(0.97); }
.ds-btn-primary:focus-visible { outline: 2px solid #8B7CE8; outline-offset: 2px; }
.ds-btn-primary:disabled { background: #D5D0C8; color: #9C8F83; cursor: default; transform: none; }
@media (prefers-reduced-motion: reduce) { .ds-btn-primary { transition: none; } .ds-btn-primary:active { transform: none; opacity: 0.72; } }

.ds-btn-tonal { display: inline-flex; align-items: center; gap: 8px; background: #EFECFE; color: #6C5BC4; border: 0; border-radius: 16px; padding: 14px 24px; font-family: Inter, sans-serif; font-size: 15px; font-weight: 600; cursor: pointer; transition: transform 220ms cubic-bezier(0.05, 0.7, 0.1, 1), background-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-btn-tonal:hover { background: #E5E1F9; }
.ds-btn-tonal:active { transform: scale(0.97); }
.ds-btn-tonal:focus-visible { outline: 2px solid #8B7CE8; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .ds-btn-tonal { transition: none; } .ds-btn-tonal:active { transform: none; opacity: 0.72; } }

.ds-input-field { background: #F5F2EE; color: #0F172A; border: 1px solid #E8E4DF; border-radius: 16px; padding: 14px 16px; font-family: Inter, sans-serif; font-size: 15px; font-weight: 400; line-height: 1.47; letter-spacing: -0.1px; transition: border-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1), box-shadow 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-input-field::placeholder { color: #9C8F83; }
.ds-input-field:hover, .ds-input-field:active { border-color: #D5D0C8; }
.ds-input-field:focus-visible { outline: 0; border-color: rgba(139, 124, 232, 0.47); box-shadow: 0 0 0 1px rgba(139, 124, 232, 0.47); }
.ds-input-field[aria-invalid="true"] { border-color: #EF4444; }
.ds-input-field[aria-invalid="true"]:focus-visible { border-color: #EF4444; box-shadow: 0 0 0 1px #EF4444; }
@media (prefers-reduced-motion: reduce) { .ds-input-field { transition: none; } }

.ds-search { position: relative; display: inline-flex; align-items: center; }
.ds-search-icon { position: absolute; left: 16px; color: #5C534A; pointer-events: none; }
.ds-input-field { background: #F5F2EE; color: #0F172A; border: 1px solid #E8E4DF; border-radius: 16px; padding: 14px 16px; font-family: Inter, sans-serif; font-size: 15px; font-weight: 400; line-height: 1.47; letter-spacing: -0.1px; transition: border-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1), box-shadow 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-search-field { padding-left: 48px; }
.ds-input-field::placeholder { color: #9C8F83; }
.ds-input-field:hover, .ds-input-field:active { border-color: #D5D0C8; }
.ds-input-field:focus-visible { outline: 0; border-color: rgba(139, 124, 232, 0.47); box-shadow: 0 0 0 1px rgba(139, 124, 232, 0.47); }
@media (prefers-reduced-motion: reduce) { .ds-input-field { transition: none; } }

.ds-nav { display: flex; width: 100%; height: 56px; background: #FFFDF9; }
.ds-nav-item { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; background: none; border: 0; padding: 0; color: #5C534A; font-family: Inter, sans-serif; cursor: pointer; transition: color 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-nav-indicator { display: grid; place-items: center; width: 64px; height: 32px; border-radius: 16px; transition: background-color 220ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-nav-label { font-size: 10px; font-weight: 400; line-height: 1; }
.ds-nav-item:hover .ds-nav-indicator { background: rgba(139, 124, 232, 0.08); }
.ds-nav-item:active .ds-nav-indicator { background: rgba(139, 124, 232, 0.1); }
.ds-nav-item:focus-visible { outline: 2px solid #8B7CE8; outline-offset: -2px; }
.ds-nav-item.ds-is-selected { color: #8B7CE8; }
.ds-nav-item.ds-is-selected .ds-nav-indicator { background: #EFECFE; }
.ds-nav-item.ds-is-selected .ds-nav-label { font-weight: 600; }
@media (prefers-reduced-motion: reduce) { .ds-nav-item, .ds-nav-indicator { transition: none; } }

.ds-chip-row { display: inline-flex; flex-wrap: wrap; gap: 8px; }
.ds-chip-row-dark { background: #1A1E2E; padding: 8px; }
.ds-chip { display: inline-flex; align-items: center; background: #F1F5F9; color: #0F172A; border: 0; border-radius: 9999px; padding: 6px 16px; font-family: Inter, sans-serif; font-size: 13px; font-weight: 500; cursor: pointer; transition: background-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1), color 120ms cubic-bezier(0.05, 0.7, 0.1, 1), transform 220ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-chip:hover { background: #E8ECF1; }
.ds-chip:active { transform: scale(0.97); }
.ds-chip:focus-visible { outline: 2px solid #8B7CE8; outline-offset: 2px; }
.ds-chip.ds-is-selected { background: #EFECFE; color: #6C5BC4; }
.ds-chip.ds-is-selected:hover { background: #E5E1F9; }
.ds-chip-dark { display: inline-flex; align-items: center; background: #252A3E; color: #F4F2FF; border: 1px solid #353B52; border-radius: 12px; padding: 4px 12px; font-family: Inter, sans-serif; font-size: 13px; font-weight: 500; cursor: pointer; transition: background-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1), transform 220ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-chip-dark:hover { background: #30344C; }
.ds-chip-dark:active { transform: scale(0.97); }
.ds-chip-dark:focus-visible { outline: 2px solid #B7ADF5; outline-offset: 2px; }
.ds-chip-dark.ds-is-selected { background: #463D6B; color: #DCD5FA; }
@media (prefers-reduced-motion: reduce) { .ds-chip, .ds-chip-dark { transition: none; } .ds-chip:active, .ds-chip-dark:active { transform: none; opacity: 0.72; } }

.ds-sticky-wrap { display: flex; flex-wrap: wrap; align-items: flex-start; gap: 24px; padding: 24px; background: #F2EFE9; }
.ds-sticky-wrap-dark { background: #1A1E2E; }
.ds-sticky { display: flex; flex-direction: column; gap: 4px; width: 200px; background: var(--tone, #FBE48E); color: #0F172A; border: 0; border-radius: 12px; padding: 14px 14px 12px; box-shadow: 3px 6px 16px #78644226, 1px 2px 4px #7864421F; transform: rotate(var(--tilt, 0deg)); transition: transform 220ms cubic-bezier(0.05, 0.7, 0.1, 1), box-shadow 220ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-sticky:hover { box-shadow: inset 0 0 0 999px rgba(139, 124, 232, 0.04), 3px 6px 16px #78644226, 1px 2px 4px #7864421F; }
.ds-sticky:active { transform: rotate(var(--tilt, 0deg)) scale(0.97); box-shadow: inset 0 0 0 999px rgba(139, 124, 232, 0.08), 3px 6px 16px #78644226, 1px 2px 4px #7864421F; }
.ds-sticky:focus-visible { outline: 2px solid #8B7CE8; outline-offset: 2px; }
.ds-sticky-title-row { display: flex; align-items: flex-start; gap: 4px; }
.ds-sticky-pin { flex: none; margin-top: 3px; color: #8B7CE8; }
.ds-sticky-title { margin: 0; font-family: Caveat, MaShanZheng, cursive; font-size: 22px; font-weight: 500; line-height: 1.2; color: #0F172A; }
.ds-sticky-body { margin: 0; font-family: Caveat, MaShanZheng, cursive; font-size: 15px; font-weight: 400; line-height: 1.45; color: #5C534A; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4; overflow: hidden; }
.ds-sticky-footer { display: flex; align-items: center; justify-content: space-between; }
.ds-sticky-time { font-family: Caveat, MaShanZheng, cursive; font-size: 17px; font-weight: 500; line-height: 1.2; color: #9C8F83; }
.ds-sticky-doodle { color: rgba(92, 83, 74, 0.59); }
.ds-sticky-dark { color: #F4F2FF; box-shadow: 3px 6px 16px #00000020, 1px 2px 4px #00000020; }
.ds-sticky-dark .ds-sticky-title { color: #F4F2FF; }
.ds-sticky-dark .ds-sticky-body { color: #C4C0E0; }
.ds-sticky-dark .ds-sticky-time { color: #9E9AB8; }
@media (prefers-reduced-motion: reduce) { .ds-sticky { transition: none; transform: none; } .ds-sticky:active { transform: none; } }

.ds-settings-group { background: #FFFDF9; border: 1px solid #E8E4DF; border-radius: 20px; padding: 4px 0; }
.ds-settings-row { display: flex; align-items: center; padding: 12px; cursor: pointer; transition: transform 120ms cubic-bezier(0.05, 0.7, 0.1, 1), background-color 120ms cubic-bezier(0.05, 0.7, 0.1, 1); }
.ds-settings-row:hover { background: rgba(139, 124, 232, 0.08); }
.ds-settings-row:active { transform: scale(0.98); background: rgba(139, 124, 232, 0.08); }
.ds-settings-row:focus-visible { outline: 2px solid #8B7CE8; outline-offset: -2px; border-radius: 8px; }
.ds-settings-divider { height: 0.5px; margin: 0 12px; background: #EBE8E3; }
.ds-icon-circle { flex: none; width: 32px; height: 32px; margin: 0 12px; border-radius: 50%; background: rgba(139, 124, 232, 0.12); color: #8B7CE8; display: grid; place-items: center; }
.ds-settings-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ds-settings-title { font-family: Inter, sans-serif; font-size: 15px; font-weight: 400; line-height: 1.47; letter-spacing: -0.1px; color: #0F172A; }
.ds-settings-subtitle { font-family: Inter, sans-serif; font-size: 13px; font-weight: 400; line-height: 1.38; color: #5C534A; }
.ds-settings-trailing { margin-left: 8px; color: #5C534A; }
.ds-settings-row.ds-is-destructive .ds-icon-circle { color: #EF4444; background: rgba(239, 68, 68, 0.12); }
.ds-settings-row.ds-is-destructive .ds-settings-title { color: #EF4444; }
.ds-settings-row.ds-is-destructive .ds-settings-subtitle { color: rgba(239, 68, 68, 0.7); }
@media (prefers-reduced-motion: reduce) { .ds-settings-row { transition: background-color 120ms linear; } .ds-settings-row:active { transform: none; } }
